mapper.select:
SELECT 
  FROM fnd11_book_extr
 WHERE fnd11_company_id  = #{companyId}
   AND fnd11_std_date    = #{stdDate}
   AND CONCAT(fnd11_fund_cd, fnd11_fund_nm, fnd11_item_cd, fnd11_item_nm) ILIKE #{searchText}
 ORDER BY fnd11_fund_cd, fnd11_item_type, fnd11_item_cd

SELECT TO_CHAR(MAX(fnd11_std_date),'yyyy-mm-dd')
  FROM fnd11_book_extr
 WHERE fnd11_company_id  = #{companyId}
   AND fnd11_std_date   <= #{stdDate}

mapper.update:
UPDATE fnd11_book_extr
   SET fnd11_std_date  = #{req.stdDate},
       fnd11_fund_cd   = #{req.fundCode},
       fnd11_fund_nm   = #{req.fundName},
       fnd11_item_cd   = #{req.itemCode},
       fnd11_item_nm   = #{req.itemName},
       fnd11_item_type = #{req.itemType}
 WHERE fnd11_book_extr_id = #{req.bookExtrId}
   AND fnd11_company_id   = #{companyId}

mapper.delete:
DELETE FROM fnd11_book_extr
 WHERE fnd11_company_id = #{companyId}
   AND fnd11_book_extr_id IN
#{bookExtrId}
